"""Detect a Cycle in a Directed Graph — three-colour iterative DFS.

Grey means "on the current path"; reaching a grey node closes a cycle. The DFS
is iterative so deep graphs cannot exhaust the recursion limit.

Time: O(V + E)   Space: O(V + E)
"""
from typing import List


class Solution:
    def hasCycleDirected(self, n: int, edges: List[List[int]]) -> bool:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)

        WHITE, GREY, BLACK = 0, 1, 2
        colour = [WHITE] * n
        for start in range(n):
            if colour[start] != WHITE:
                continue
            stack = [(start, iter(graph[start]))]
            colour[start] = GREY
            while stack:
                node, neighbours = stack[-1]
                advanced = False
                for nxt in neighbours:
                    if colour[nxt] == GREY:
                        return True
                    if colour[nxt] == WHITE:
                        colour[nxt] = GREY
                        stack.append((nxt, iter(graph[nxt])))
                        advanced = True
                        break
                if not advanced:
                    colour[node] = BLACK
                    stack.pop()
        return False
